const functions=require("firebase-functions"),admin=require("firebase-admin"),{getFollowerCount:getFollowerCount,getIgSessionIg:getIgSessionIg}=require("follower-count");admin.initializeApp();const db=admin.firestore();exports.updateInstagramFollowerCount=functions.https.onCall((async(data,context)=>{const{uid:uid,instagramUsername:instagramUsername}=data;if(!uid||!instagramUsername)throw new functions.https.HttpsError("invalid-argument","Missing uid or username.");try{const sessionId=await getIgSessionIg(process.env.INSTAGRAM_USERNAME,process.env.INSTAGRAM_PASSWORD),count=await getFollowerCount({type:"instagram",username:instagramUsername,sessionId:sessionId});if("number"!=typeof count)throw new Error("Follower count not found.");return await db.collection("users").doc(uid).update({instagramFollowerCount:count,instagramLastChecked:admin.firestore.FieldValue.serverTimestamp()}),{success:!0,count:count}}catch(error){throw console.error("Error fetching Instagram follower count:",error.message),new functions.https.HttpsError("internal",error.message)}}));